<?php

namespace App\Http\Controllers\Api;

use App\Http\Controllers\Controller;
use App\Http\Resources\CreditNoteResource;
use App\Models\CreditNote;
use App\Services\Sri\SriService;
use App\Services\WorkspacePermissionService;
use App\Support\ActiveWorkspace;
use Illuminate\Http\Resources\Json\AnonymousResourceCollection;
use Illuminate\Support\Facades\Auth;
use Illuminate\Validation\ValidationException;

/**
 * Read-only credit-note listing for the active workspace (WorkspaceScope
 * isolated). Credit notes are generated by InvoiceService when an invoice with
 * payments is voided — never created directly here.
 */
class CreditNoteController extends Controller
{
    public function index(
        WorkspacePermissionService $permissions,
        ActiveWorkspace $activeWorkspace,
    ): AnonymousResourceCollection {
        // An employed doctor (clinical-only member) only sees credit notes for
        // THEIR OWN attentions — a colleague's billing is not theirs to read
        // (same self-scoping as InvoiceController).
        $ownDoctorId = $permissions->selfScopedDoctorId(Auth::user(), $activeWorkspace->current());

        $creditNotes = CreditNote::query()
            ->with('invoice')
            ->when($ownDoctorId, fn ($q, $d) => $q->whereHas(
                'invoice', fn ($iq) => $iq->where('attending_doctor_id', $d),
            ))
            ->latest('issued_at')
            ->latest('id')
            ->paginate(20);

        return CreditNoteResource::collection($creditNotes);
    }

    /** Re-queue a rejected credit note for SRI authorization. */
    public function retrySri(int $id, SriService $sri): CreditNoteResource
    {
        $creditNote = CreditNote::findOrFail($id);

        if (! $sri->resend($creditNote)) {
            throw ValidationException::withMessages([
                'sri' => 'Este comprobante ya fue autorizado por el SRI; no se puede reenviar.',
            ]);
        }

        $creditNote->forceFill(['sri_error' => null])->save();

        return CreditNoteResource::make($creditNote->fresh());
    }
}
